import {paintOccasionBorder,mimoPaperEdge,mimoSeal,mimoPhotoTabs,mimoLabel} from './gift-identity.js';
import {cleanBookFinish,resolveBookFinish} from './book-finish.js';
import {coverOptions} from './cover-catalog.js';
import {giftArtworkSource,appearancePalette,drawGiftBackground} from './appearance.js';
import {cleanAppearance} from './appearance.js';
import {cleanStationery} from './stationery.js';
import {occasions} from './occasions.js';
import {cleanStoryDesign} from './story-design.js';
import {loadImage,drawCover} from './paper.js';
import {drawWrapped} from './text-layout.js';
const origin=location.origin;
export function publicReceiptUrl(data){if(data.publicUrl){try{const url=new URL(data.publicUrl);if(url.origin===origin&&/^\/g\/[a-f0-9]{32}$/.test(url.pathname))return url.href;}catch{}}return '';}
export function receiptUrl(data){const published=publicReceiptUrl(data);if(published)return published;const compact=(value,defaults)=>Object.fromEntries(Object.entries(value).filter(([key,item])=>JSON.stringify(item)!==JSON.stringify(defaults[key])));const payload=data.format==='stories'?{storyDesign:compact(cleanStoryDesign(data.storyDesign),cleanStoryDesign()),...(Object.keys(compact(cleanAppearance(data.appearance),cleanAppearance())).length?{appearance:compact(cleanAppearance(data.appearance),cleanAppearance())}:{})}:{appearance:compact(cleanAppearance(data.appearance),cleanAppearance()),stationeryDesign:compact(cleanStationery(data.stationeryDesign),cleanStationery())};if(data.format==='livro')payload.bookFinish=resolveBookFinish(data);for(const key of ['recipient','message','color','occasion','format','character','person','texture','pattern','eventDate','eventPlace','wedding','model','coverArt','openingStyle'])payload[key]=data[key];const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary='';bytes.forEach(b=>binary+=String.fromCharCode(b));return origin+'/#receber='+btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
export function readReceipt(){if(!location.hash.startsWith('#receber='))return null;try{const raw=location.hash.slice(9);if(raw.length>5000)return null;const binary=atob(raw.replace(/-/g,'+').replace(/_/g,'/'));const data=JSON.parse(new TextDecoder().decode(Uint8Array.from(binary,c=>c.charCodeAt(0))));const clean={};for(const [key,max] of [['recipient',34],['message',180],['eventDate',10],['eventPlace',60],['model',40]])clean[key]=String(data[key]||'').slice(0,max);if(['stories','livro','cartao','convite'].includes(data.format))clean.format=data.format;if(Object.hasOwn(occasions,data.occasion))clean.occasion=data.occasion;if(['none','capy','people'].includes(data.character))clean.character=data.character;if(Number.isInteger(data.person)&&data.person>=0&&data.person<12)clean.person=data.person;if(/^#[0-9A-Fa-f]{6}$/.test(data.color))clean.color=data.color;if(['linho','algodao','kraft'].includes(data.texture))clean.texture=data.texture;if(/^(signature|natal|aniversario|casamento|maes|pais|namorados|pascoa|amizade)-[0-3]$/.test(data.pattern))clean.pattern=data.pattern;for(const key of ['coverArt','openingStyle'])if(['natal','aniversario','casamento','familia','amor','pascoa','conquistas','pet'].includes(data[key]))clean[key]=data[key];if(data.format==='livro'&&data.bookFinish&&typeof data.bookFinish==='object')clean.bookFinish=cleanBookFinish(data.bookFinish);clean.storyDesign=cleanStoryDesign(data.storyDesign);clean.stationeryDesign=cleanStationery(data.stationeryDesign);clean.appearance=cleanAppearance(data.appearance);clean.wedding=data.wedding==='invite'?'invite':'gift';return clean;}catch{return null;}}
export function createQRControls(getData,onChange){const details=document.createElement('details');details.className='options-panel qr-panel';details.innerHTML='<summary>Cartão digital com QR Code</summary><p>Arquivo digital para baixar. Não enviamos cartão físico; se quiser, você pode imprimir o arquivo.</p><div class="field"><label for="qr-collection">Coleção do cartão QR · 30 por ocasião</label><select id="qr-collection"></select></div><div class="qr-style-options"><button data-qr-style="carta" aria-pressed="true">Carta</button><button data-qr-style="retrato" aria-pressed="false">Retrato</button><button data-qr-style="selo" aria-pressed="false">Selo</button></div><canvas class="qr-card-preview" width="720" height="960" role="img" aria-label="Prévia do cartão com QR Code"></canvas><button class="download-qr" type="button">Baixar cartão com QR</button><p class="qr-status" role="status"></p><p class="qr-explanation">Prévia privada. O QR leva a mensagem principal e o visual deste mimo; as fotos e as outras páginas ficam neste aparelho. O acesso segue a permissão desta página.</p>';
 if(['localhost','127.0.0.1'].includes(location.hostname))details.querySelector('.qr-explanation').textContent='Prévia local. Este QR abre neste computador; ainda não é um link de entrega. A mensagem principal vai no QR, mas fotos e outras páginas ficam neste aparelho.';
 document.querySelector('.customizer-bottom').before(details);const canvas=details.querySelector('canvas'),ctx=canvas.getContext('2d');let version=0;const download=details.querySelector('.download-qr'),status=details.querySelector('.qr-status');download.disabled=true;const collection=details.querySelector('#qr-collection');collection.addEventListener('change',()=>onChange({qrCoverId:collection.value}));
 async function render(force=false){const current=++version;download.disabled=true;delete canvas.dataset.qrUrl;delete canvas.dataset.qrBounds;delete canvas.dataset.qrModules;const source=getData(),published=publicReceiptUrl(source);details.querySelector('.qr-explanation').textContent=published?'Este QR abre a versão publicada, com fotos, páginas e áudio. Publique novamente depois de editar para atualizar o presente.':['localhost','127.0.0.1'].includes(location.hostname)?'Prévia local. Este QR abre neste computador; ainda não é um link de entrega. A mensagem principal vai no QR, mas fotos e outras páginas ficam neste aparelho.':'Prévia do rascunho. O QR leva a mensagem principal e o visual deste mimo; fotos, áudio e outras páginas só ficam disponíveis no link publicado.';const covers=coverOptions(source.occasion,'cartao');if(collection.dataset.occasion!==source.occasion){collection.dataset.occasion=source.occasion;collection.replaceChildren(new Option('Usar acabamento rápido',''),...covers.map(item=>new Option(String(item.number).padStart(2,'0')+' · '+item.name,item.id)));}collection.value=source.qrCoverId||'';if(!details.open&&force!==true)return false;status.textContent='Preparando cartão com QR…';try{const data=source,url=receiptUrl(data);if(typeof window.qrcode!=='function')throw Error('qr-unavailable');let qr;try{qr=window.qrcode(0,'M');qr.addData(url);qr.make();}catch{throw Error(published?'qr-unavailable':'qr-too-large');}const cover=covers.find(item=>item.id===data.qrCoverId),colors=appearancePalette(cover?.appearance||data.appearance);const [pattern,art,photo]=await Promise.all([loadImage(giftArtworkSource(cover?{coverArt:cover.family}:data)).catch(()=>null),loadImage('assets/'+data.theme.sheet+'.webp'),data.photo?loadImage(data.photo).catch(()=>null):null]);await document.fonts.ready;if(version!==current)return false;ctx.fillStyle=data.color;ctx.fillRect(0,0,720,960);if(cover){drawGiftBackground(ctx,720,960,{palette:colors,background:cover.appearance.background,pattern,intensity:.4});ctx.save();ctx.strokeStyle=colors.accent;ctx.lineWidth=2;const layout=Math.floor((cover.number-1)/3);for(let i=0;i<=layout;i++){const inset=8+i*2;ctx.strokeRect(inset,inset,720-inset*2,960-inset*2);}ctx.restore();}else if(pattern)drawCover(ctx,pattern,0,0,720,960);ctx.fillStyle='#fffaf2';ctx.beginPath();ctx.roundRect(28,28,664,904,25);ctx.fill();ctx.strokeStyle=cover?colors.accent:data.color;ctx.lineWidth=cover?2:7;ctx.beginPath();ctx.roundRect(40,40,640,880,20);ctx.stroke();mimoLabel(ctx,'feito para você',248,47,224,34,{paper:'#fff0c5',ink:'#3a1e14'});ctx.fillStyle='#4b2c28';ctx.textAlign='center';ctx.textBaseline='top';ctx.font='38px "Fraunces",Georgia';drawWrapped(ctx,data.recipient?'Para '+data.recipient:'Um mimo para você',360,93,600,43,2);const cell=art.width/4;if(data.qrStyle==='retrato'){ctx.fillStyle='#d9e5ec';ctx.beginPath();ctx.arc(360,255,74,0,Math.PI*2);ctx.fill();}if(data.qrStyle==='retrato'&&photo){const scale=Math.min(270/photo.width,130/photo.height),pw=photo.width*scale,ph=photo.height*scale;ctx.fillStyle='#fffdf8';ctx.strokeStyle='#3a1e14';ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(352-pw/2,182,pw+16,ph+16,12);ctx.fill();ctx.stroke();ctx.drawImage(photo,360-pw/2,190,pw,ph);mimoPhotoTabs(ctx,352-pw/2,182,pw+16,ph+16,{scale:1.5});}else mimoSeal(ctx,art,data.theme,360,255,101,{ink:'#3a1e14',paper:'#fffdf8',accent:'#e8473a'});
  {const n=qr.getModuleCount(),unit=Math.floor(400/(n+8)),box=unit*(n+8),left=Math.floor((720-box)/2),top=350;ctx.fillStyle='#ffffff';ctx.fillRect(150,340,420,420);ctx.fillStyle='#000000';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))ctx.fillRect(left+(x+4)*unit,top+(y+4)*unit,unit,unit);canvas.dataset.qrBounds=JSON.stringify({left,top,width:box,height:box});canvas.dataset.qrUrl=url;canvas.dataset.qrModules=String(n);}
  ctx.fillStyle='#4b2c28';ctx.font='28px Nunito,Arial';ctx.fillText('Aponte a câmera para abrir.',360,793);ctx.font='22px Nunito,Arial';ctx.fillText('Uma lembrança feita para você.',360,842);if(data.qrStyle==='selo'){ctx.strokeStyle=data.color;ctx.lineWidth=3;ctx.strokeRect(43,43,634,874);}mimoPaperEdge(ctx,720,960,{ink:'#3a1e14',soft:'#f6d5d5'});paintOccasionBorder(ctx,720,960,cover?{...data,appearance:cover.appearance}:data,colors);details.querySelectorAll('[data-qr-style]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.qrStyle===(data.qrStyle||'carta'))));status.textContent='Cartão com QR pronto para baixar.';download.disabled=false;return current;}catch(error){if(version!==current)return false;ctx.clearRect(0,0,canvas.width,canvas.height);delete canvas.dataset.qrUrl;delete canvas.dataset.qrBounds;delete canvas.dataset.qrModules;status.textContent=error.message==='qr-too-large'?'Sua personalização ficou grande para um QR de rascunho. Publique seu presente para gerar um link compacto, com todas as fotos e mensagens. Seu conteúdo foi preservado.':'Não foi possível preparar o cartão com QR. Tente novamente; seu conteúdo foi preservado.';download.disabled=true;return false;}}
 details.addEventListener('toggle',render);mimoPaperEdge(ctx,720,960,{ink:'#3a1e14',soft:'#f6d5d5'});details.querySelectorAll('[data-qr-style]').forEach(b=>b.addEventListener('click',()=>onChange({qrStyle:b.dataset.qrStyle})));details.querySelector('.download-qr').addEventListener('click',async()=>{const ticket=await render(true);if(!ticket||ticket!==version||!canvas.dataset.qrUrl)return;try{const a=document.createElement('a');a.download='meu-mimo-cartao-qr.png';a.href=canvas.toDataURL('image/png');a.click();}catch{status.textContent='Não foi possível baixar o cartão com QR. Tente novamente; seu conteúdo foi preservado.';}});return {render};}
